package workbench.reactive.l04;

import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;

import java.math.BigDecimal;
import java.time.Duration;

/** A cake's weight and the price per kilogram change at different times. zip vs combineLatest. */
public class CombineLatestDemo {
    static Flux<BigDecimal> weights() {    // 1.5 kg at 0 ms, 2.0 kg at 300 ms
        return Flux.concat(Mono.just(new BigDecimal("1.5")), Mono.just(new BigDecimal("2.0")).delayElement(Duration.ofMillis(300)));
    }

    static Flux<BigDecimal> pricesPerKg() {   // 20.00 at 100 ms, 22.00 at 200 ms, 21.00 at 400 ms
        return Flux.just("20.00", "22.00", "21.00").map(BigDecimal::new)
                .zipWith(Flux.just(100L, 100L, 200L), (price, wait) -> Mono.just(price).delayElement(Duration.ofMillis(wait)))
                .concatMap(m -> m);
    }

    public static void main(String[] args) {
        System.out.println("zip:           " + Flux.zip(weights(), pricesPerKg(), BigDecimal::multiply).collectList().block());
        System.out.println("combineLatest: " + Flux.combineLatest(weights(), pricesPerKg(), BigDecimal::multiply).collectList().block());
    }
}

